package com.neml.badminton.controller;import com.neml.badminton.dto.AdministrativeConfigurationDtos.*;import com.neml.badminton.entity.User;import com.neml.badminton.service.AdministrativeConfigurationService;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController@RequestMapping("/api/championships/{championshipId}/administrative-configuration")public class AdministrativeConfigurationController{private final AdministrativeConfigurationService service;public AdministrativeConfigurationController(AdministrativeConfigurationService service){this.service=service;}@GetMapping("/branding")@PreAuthorize("@championshipSecurity.canView(#championshipId,authentication)")public BrandingDto branding(@PathVariable UUID championshipId){return service.branding(championshipId);}@PutMapping("/branding")@PreAuthorize("@championshipSecurity.canManage(#championshipId,authentication)")public BrandingDto branding(@PathVariable UUID championshipId,@Valid@RequestBody BrandingRequest r,@AuthenticationPrincipal User actor){return service.updateBranding(championshipId,r,actor);}@GetMapping("/auction")@PreAuthorize("@championshipSecurity.canView(#championshipId,authentication)")public AuctionConfigDto auction(@PathVariable UUID championshipId){return service.auction(championshipId);}@PutMapping("/auction")@PreAuthorize("@championshipSecurity.canManage(#championshipId,authentication)")public AuctionConfigDto auction(@PathVariable UUID championshipId,@Valid@RequestBody AuctionConfigRequest r,@AuthenticationPrincipal User actor){return service.updateAuction(championshipId,r,actor);}}
